import {orderCases,orderCopy as copy} from './ribbon-orders-content.mjs';
import {createOrder,orderModel,changeOrder,orderExample,orderExplanation} from './ribbon-orders-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=(text,speech)=>`<p data-ro-read${speech?` data-ro-speech="${esc(speech)}"`:''}>${esc(text)}</p>`;
const count=(n,name)=>`${n} ${name}${n===1?'':'s'}`;
const button=(action,text,disabled=false)=>`<button type="button" data-ro-action="${action}"${disabled?' disabled':''}>${esc(text)}</button>`;
let visit=null,retire=()=>{},stopBinding=()=>{};
export function resetRibbonOrders(){retire();stopBinding();visit=null;retire=()=>{};stopBinding=()=>{};}
function current(book,owner){if(!visit||visit.book!==book||visit.owner!==owner){retire();stopBinding();visit={book,owner,caseId:orderCases[0].id,cases:new Map(orderCases.map(c=>[c.id,createOrder(c.id)])),screen:'work',frame:0,caller:'work',grownUp:false};}return visit;}

// Both trays use the same 504-unit whole and the same piece width.
function diagram(m,owner,claim=false){
 const d=m.denominator,bundles=owner==='rack'?m.bundles:[],ids=owner==='rack'?m.loose:m.sent;
 const rows=[...bundles.map(ids=>({ids,bundled:true})),...Array.from({length:Math.ceil(ids.length/d)},(_,j)=>({ids:ids.slice(j*d,(j+1)*d),bundled:false}))];
 if(!rows.length)rows.push({ids:[],bundled:false});
 const finalRow=rows.length-1,endpoint=48+504*rows[finalRow].ids.length/d,endpointY=18+48*finalRow;
 const marker=claim?`<path data-ro-claim-marker data-endpoint="${endpoint}" d="M${endpoint} ${endpointY-12}v39m-7-31 7-7 7 7"/>`:"";
 const prefix=claim?'ro-claim':`ro-${owner}`;
 const strips=rows.map((row,j)=>{const y=18+48*j;return `<g><rect data-ro-whole x="48" y="${y}" width="504" height="24"/>${row.ids.map((id,k)=>`<rect ${claim?'data-ro-claim-piece':`data-ro-piece="${id}" data-ro-owner="${owner}"`} x="${48+504*k/d}" y="${y}" width="${504/d}" height="24" fill="url(#${prefix}-pattern)"/>`).join('')}${Array.from({length:d-1},(_,k)=>`<path class="ro-cut" d="M${48+504*(k+1)/d} ${y}v24"/>`).join('')}<rect class="ro-outline" x="48" y="${y}" width="504" height="24"/>${row.bundled?`<path data-ro-bundle="${j}" d="M44 ${y-3}v30H556v-30"/>`:''}<text x="48" y="${y+40}" text-anchor="middle">0</text><text x="552" y="${y+40}" text-anchor="middle">1</text></g>`;}).join('');
 return `<svg ${claim?'data-ro-claim':`data-ro-diagram="${owner}"`} viewBox="0 0 600 ${48*rows.length+30}" role="img" aria-label="${claim?'Different claim':owner==='rack'?'Current ribbon rack':'Current order tray'}: ${count(bundles.length*d+ids.length,'piece')}; ${d} equal pieces per whole."><defs><pattern id="${prefix}-pattern" width="10" height="10" patternUnits="userSpaceOnUse"><rect width="10" height="10" class="ro-pattern-base"/>${owner==='rack'?'<path d="M-2 2L2-2M0 10L10 0M8 12L12 8M0 0L10 10" class="ro-hatch"/>':'<circle cx="5" cy="5" r="1.5" class="ro-dot"/>'}</pattern></defs>${strips}${marker}</svg>`;
}
function material(m){return `${p(`One whole contains ${m.denominator} pieces of size 1/${m.denominator}.`)}<div class="ro-trays"><section class="ro-tray ro-rack" aria-label="Current ribbon rack"><h3>Ribbon rack</h3>${diagram(m,'rack')}${p(`${count(m.packed,'whole bundle')} and ${count(m.loose.length,'loose piece')}. ${count(m.remaining,'piece')} on the rack.`)}</section><section class="ro-tray ro-order" aria-label="Current order tray"><h3>Order tray</h3>${diagram(m,'order')}${p(`${count(m.sentCount,'piece')} sent. ${count(m.needed,'piece')} still requested.`)}</section></div>`;}
function ticket(m){return `<div class="ro-ticket">${p(`Starting stock: ${m.stockName}.`,m.stockSpeech?`Starting stock: ${m.stockSpeech}.`:null)}${p(`Ribbon order: ${m.orderName}.`,m.orderSpeech?`Ribbon order: ${m.orderSpeech}.`:null)}</div>`;}
function work(v,m){return `<label class="ro-case">Choose a ribbon order<select data-ro-case>${orderCases.map(c=>`<option value="${c.id}"${c.id===v.caseId?' selected':''}>${esc(c.title)}</option>`).join('')}</select></label>${p(copy.story)}${p(copy.instruction)}${ticket(m)}${material(m)}<div class="ro-progress" role="status">${p(m.readout)}</div><section aria-label="Ribbon order controls"><div class="ro-actions">${button('open','Open one whole',!m.canOpen)}${button('whole','Send one whole',!m.canWhole)}${button('piece','Send one piece',!m.canPiece)}${button('undo','Undo last move',!m.canUndo)}</div><div class="ro-guidance">${m.guidance.map(t=>p(t)).join('')}</div></section><div class="ro-actions">${button('explain','Explain this subtraction')}${button('example','Show me with quarters')}</div>`;}
function explanation(v,m){const e=orderExplanation(v.cases.get(v.caseId));return `${ticket(m)}${material(m)}<div class="ro-explanation">${p(e.text,e.spokenText)}</div><div class="ro-actions">${button('back','Back to my order')}${button('example','Show me with quarters')}</div>`;}
function example(v){const e=orderExample(v.frame);return `${p('These are separate example ribbons. Your order stays as you left it.')}${material(e)}${e.claim?`<section class="ro-comparison" aria-label="Different claim">${p('Different claim: 2 wholes and 2/4.','Different claim: two wholes and two quarters.')}${diagram({denominator:e.claim.denominator,bundles:[[0,1,2,3],[4,5,6,7]],loose:[8,9]},'rack',true)}</section>`:''}<div class="ro-caption" role="status">${p(`Picture ${v.frame+1} of 6. ${e.text}`,`Picture ${v.frame+1} of 6. ${e.spokenText??e.text}`)}</div><nav class="ro-actions" aria-label="Example pictures">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===5)}${button('back',v.caller==='explanation'?'Back to the subtraction':'Back to my order')}</nav>`;}
export function ribbonOrdersPage(book,owner){const v=current(book,owner),m=orderModel(v.cases.get(v.caseId));return `<section class="ro-page" data-ro-root><h2 id="ro-heading" tabindex="-1" data-ro-read>${v.screen==='work'?'Ribbon Orders':v.screen==='explanation'?'Explain this subtraction':'Show me with quarters'}</h2><div data-ro-view="${v.screen}"${v.screen==='example'?` data-ro-frame="${v.frame}"`:''}>${v.screen==='example'?example(v):v.screen==='explanation'?explanation(v,m):work(v,m)}</div><div class="ro-actions">${hearButton('',v.screen==='example'?'Read this example':v.screen==='explanation'?'Read this subtraction':'Read this order')}</div>${p(copy.visit)}<details data-ro-grownup${v.grownUp?' open':''}><summary>For grown-ups</summary>${p(copy.grownUp)}</details></section>`;}

// A removed, concealed or reparented control stays retired for this binding.
function bindingGuard(root,valid,stop){const controls=[root,...root.querySelectorAll('button,input,select,a,summary,details')].filter(n=>!n.closest?.('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.target.closest?.('.speech-controls,drawn-howto'))continue;if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const disconnect=()=>{disconnected=true;observer.disconnect();};const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();disconnect();}});observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return {disconnect,accepts(node){audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(node)||node.disabled||retired.has(node))return false;const old=chains.get(node),now=chain(node);if(!old||old.length!==now.length||!old.every((n,i)=>n===now[i]))return false;for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;}};
}
function visibleNarration(root){return [...root.querySelectorAll('[data-ro-read],label')].filter(n=>{if(n.closest('.speech-controls,drawn-howto'))return false;for(let a=n;a;a=a.parentElement){const css=getComputedStyle(a);if(a.hidden||a.inert||a.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility)||a.tagName==='DETAILS'&&!a.open)return false;}return n.getClientRects().length>0;}).map(n=>n.matches('label')?[...n.childNodes].map(c=>c.nodeType===3?c.textContent:c.tagName==='SELECT'?c.selectedOptions[0]?.textContent:'').join(' '):(n.dataset.roSpeech??n.textContent)).map(s=>s.replace(/\s+/g,' ').trim()).join(' ');}
export function bindRibbonOrders(book,ctx={}){retire();const root=document.querySelector('[data-ro-root]');if(!root||!visit)return;const v=visit,owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,caseId=v.caseId,material=v.cases.get(caseId),bytes=JSON.stringify(material),screen=v.screen,frame=v.frame,caller=v.caller,parent=root.parentNode;
 const live=()=>root.isConnected&&root.parentNode===parent&&document.querySelector('[data-ro-root]')===root&&location.hash==='#workshop/join-pieces'&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook??book)===book&&(!ctx.isActive||ctx.isActive())&&(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)===owner&&visit===v&&v.book===book&&v.owner===owner&&v.caseId===caseId&&v.cases.get(caseId)===material&&JSON.stringify(material)===bytes&&v.screen===screen&&v.frame===frame&&v.caller===caller;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},guard=bindingGuard(root,live,stop);retire=guard.disconnect;stopBinding=stop;
 for(const c of root.querySelectorAll('button,input,select,a,summary,details')){if(c.closest('.speech-controls,drawn-howto'))continue;for(const type of ['click','input','change','keydown'])c.addEventListener(type,e=>{if(!guard.accepts(c)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});}
 const redraw=(selector='#ro-heading')=>{guard.disconnect();ctx.render();let target=document.querySelector(selector);if(!target||target.disabled||!target.getClientRects().length)selector='#ro-heading';if(ctx.focus)ctx.focus(selector);else document.querySelector(selector)?.focus();};
 root.querySelector('[data-ro-grownup]')?.addEventListener('toggle',e=>{if(guard.accepts(e.target)&&v.grownUp!==e.target.open){v.grownUp=e.target.open;stop();}});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-speak]');if(!b||!root.contains(b)||b.closest('.speech-controls,drawn-howto'))return;if(!guard.accepts(b)){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=visibleNarration(root);},{capture:true});
 root.querySelector('[data-ro-case]')?.addEventListener('change',e=>{if(!guard.accepts(e.target)||screen!=='work'||!v.cases.has(e.target.value)||caseId===e.target.value)return;stop();v.caseId=e.target.value;redraw('[data-ro-case]');});
 root.querySelectorAll('[data-ro-action]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b))return;const a=b.dataset.roAction;
  if(a==='example'&&screen!=='example'){stop();v.caller=screen;v.screen='example';v.frame=0;redraw();return;}
  if(a==='back'&&screen!=='work'){stop();v.screen=screen==='example'?caller:'work';redraw(`[data-ro-action="${screen==='example'?'example':'explain'}"]`);return;}
  if(screen==='example'&&['previous','next'].includes(a)){const n=frame+(a==='next'?1:-1);if(!orderExample(n))return;stop();v.frame=n;redraw(`[data-ro-action="${n===5?'previous':n===0?'next':a}"]`);return;}
  if(screen!=='work')return;if(a==='explain'){stop();v.screen='explanation';redraw();return;}
  if(!['open','whole','piece','undo'].includes(a))return;const next=changeOrder(material,a);if(!next)return;stop();v.cases.set(caseId,next);const m=orderModel(next),enabled={open:m.canOpen,whole:m.canWhole,piece:m.canPiece,undo:m.canUndo},focus=enabled[a]?a:['piece','whole','open','undo'].find(x=>enabled[x]);redraw(focus?`[data-ro-action="${focus}"]`:'#ro-heading');
 }));
}
